await page.goto('https://devdocs.io/javascript/');
await cu.fill('Search', 'Array.prototype.flat');
await cu.press('Search', 'Enter');
return await page.evaluate(() => { const text = document.body.innerText; const h = [...document.querySelectorAll('h1,h2,h3')].map(x=>x.innerText); const exact = [...document.querySelectorAll('a')].find(a=>/flat/.test(a.innerText)); return cu.claim({url:location.href,title:document.title,h1:document.querySelector('h1')?.innerText,key_text:text.includes('flat') ? text.match(/.{0,40}flat.{0,80}/i)?.[0] : '',values:h,answer:exact?.innerText || h.find(x=>x==='flat') || ''}); });
